function initTopicFilter(e=document){const t=e.querySelectorAll("[data-topic]"),n=e.querySelectorAll(".research-card");if(!t.length||!n.length)return;t.forEach(e=>{e.addEventListener("click",()=>{const s=e.dataset.topic;t.forEach(t=>t.classList.toggle("is-active",t===e)),n.forEach(e=>{const t=e.dataset.topics||"";e.hidden=s!=="all"&&!t.includes(s)})})})}window.DualityModules=window.DualityModules||{},window.DualityModules.initTopicFilter=initTopicFilter